/** Real child-JVM termination at publication boundaries; this does not simulate loss of the host/device cache. */
class LmdbBulkLoadPublicationRecoveryTest {

	private static final String INPUT = "<urn:s> <urn:p> \"a\\nb\"^^<urn:\\u0064> .\n"
			+ "<urn:s2> <urn:p> <<( <urn:s> <urn:p> <urn:o> )>> <urn:g> .\n";
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final Set<Statement> EXPECTED = Set.of(
			VF.createStatement(VF.createIRI("urn:s"), VF.createIRI("urn:p"),
					VF.createLiteral("a\nb", VF.createIRI("urn:d"))),
			VF.createStatement(VF.createIRI("urn:s2"), VF.createIRI("urn:p"),
					VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:p"), VF.createIRI("urn:o")),
					VF.createIRI("urn:g")));

	@TempDir
	Path temporaryDirectory;

	@ParameterizedTest
	@EnumSource(value = PublicationStage.class, names = { "MANIFEST_DURABLE", "ARTIFACT_MOVED", "GENERATION_REMOVED",
			"ARTIFACTS_DURABLE", "PUBLICATION_DIRECTORY_DURABLE", "MARKER_REMOVED", "MARKER_REMOVAL_DURABLE",
			"MANIFEST_REMOVED", "MANIFEST_REMOVAL_DURABLE" })
	@Timeout(value = 90, unit = TimeUnit.SECONDS)
	void recoversAfterSynchronizedChildJvmTermination(PublicationStage cut) throws Exception {
		Path target = temporaryDirectory.resolve("store-" + cut);
		String java = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		Process child = new ProcessBuilder(java, "-ea", "-cp", System.getProperty("java.class.path"),
				WriterMain.class.getName(), target.toString(), cut.name()).redirectErrorStream(true).start();
		BufferedReader output = new BufferedReader(new InputStreamReader(child.getInputStream(), UTF_8));
		ExecutorService reader = Executors.newSingleThreadExecutor();
		try {
			Future<Boolean> reached = reader.submit(() -> {
				String line;
				while ((line = output.readLine()) != null) {
					System.out.println("publication-child " + cut + ": " + line);
					if (line.equals("CUT " + cut)) {
						return true;
					}
				}
				return false;
			});
			assertTrue(reached.get(60, TimeUnit.SECONDS), "Child exited before reaching " + cut);
			child.destroyForcibly();
			assertTrue(child.waitFor(10, TimeUnit.SECONDS), "Owned child failed to terminate");
		} finally {
			child.destroyForcibly();
			assertTrue(child.waitFor(10, TimeUnit.SECONDS), "Owned child survived cleanup");
			output.close();
			reader.shutdownNow();
			assertTrue(reader.awaitTermination(10, TimeUnit.SECONDS), "Child output reader survived cleanup");
		}

		boolean recoveryMetadata = Files.exists(target.resolve(LmdbBulkLoadGeneration.MANIFEST_FILE_NAME));
		LmdbBulkLoader loader = builder(target).build();
		if (recoveryMetadata) {
			LmdbBulkLoader.Result result = loader.load(new UnreadableInput(), "urn:must-not-be-read:",
					RDFFormat.NQUADS);
			assertEquals(2L, result.parsedStatements());
			assertEquals(2L, result.storedStatements());
		} else {
			// Both metadata files are gone: publication completed, so a new load must preserve the existing store.
			IOException failure = assertThrows(IOException.class,
					() -> loader.load(new UnreadableInput(), "urn:must-not-be-read:", RDFFormat.NQUADS));
			assertTrue(failure.getMessage().contains("target must be empty"));
		}
		assertFalse(Files.exists(target.resolve(LmdbBulkLoadGeneration.MARKER_FILE_NAME)));
		assertFalse(Files.exists(target.resolve(LmdbBulkLoadGeneration.MANIFEST_FILE_NAME)));
		assertEquals(EXPECTED, read(target));
		assertEquals(EXPECTED, read(target));
	}

	private static LmdbBulkLoader.Builder builder(Path target) {
		return LmdbBulkLoader.builder(target, new LmdbStoreConfig("spoc,psoc"))
				.parserMode(LmdbBulkLoader.ParserMode.FAST)
				.partitionCount(4)
				.workers(1)
				.memoryBudgetBytes(64L * 1024 * 1024)
				.maxOpenFiles(32);
	}

	private static Set<Statement> read(Path target) {
		SailRepository repository = new SailRepository(
				new LmdbStore(target.toFile(), new LmdbStoreConfig("spoc,psoc")));
		repository.init();
		try (RepositoryConnection connection = repository.getConnection();
				var statements = connection.getStatements(null, null, null, false)) {
			return statements.stream().collect(Collectors.toSet());
		} finally {
			repository.shutDown();
		}
	}

	private static final class UnreadableInput extends InputStream {
		@Override
		public int read() throws IOException {
			throw new IOException("Publication recovery must not read input again");
		}
	}

	public static final class WriterMain {
		public static void main(String[] arguments) throws IOException {
			Path target = Path.of(arguments[0]);
			PublicationStage cut = PublicationStage.valueOf(arguments[1]);
			builder(target).publicationHook(new LmdbBulkLoadGeneration.PromotionHook() {
				@Override
				public void beforeMove(int index, Path source, Path destination) {
				}

				@Override
				public void onStage(PublicationStage stage) throws IOException {
					if (stage == cut) {
						System.out.println("CUT " + stage);
						System.out.flush();
						// The parent owns the termination. A closed control pipe is an unexpected test failure.
						System.in.read();
						throw new IOException("Publication cut was released without child termination");
					}
				}
			}).build().load(new ByteArrayInputStream(INPUT.getBytes(UTF_8)), "urn:test:", RDFFormat.NQUADS);
			throw new AssertionError("Publication did not reach " + cut);
		}
	}
}
